async def _create_work_item(
    wit_client,
    project: str,
    work_item_type: Optional[str],
    fields: Optional[Dict[str, Any]]
) -> Dict[str, Any]:
    """Create a new work item."""
    try:
        if not work_item_type:
            return {
                "status": "error",
                "error_message": "work_item_type is required for create_work_item operation"
            }
        
        if not fields:
            return {
                "status": "error",
                "error_message": "fields dictionary is required for create_work_item operation"
            }
        
        # Build JSON patch document
        document = []
        for field_path, value in fields.items():
            document.append(JsonPatchOperation(
                op='add',
                path=f'/fields/{field_path}',
                value=value
            ))
        
        # Create work item
        work_item = wit_client.create_work_item(
            document=document,
            project=project,
            type=work_item_type
        )
        
        return {
            "status": "success",
            "result": {
                "id": work_item.id,
                "url": work_item.url,
                "fields": work_item.fields
            }
        }
    
    except Exception as e:
        return {
            "status": "error",
            "error_message": f"Failed to create work item: {str(e)}"
        }


