async def _query_work_items(
    wit_client,
    project: str,
    wiql_query: Optional[str]
) -> Dict[str, Any]:
    """Query work items using WIQL."""
    try:
        if not wiql_query:
            return {
                "status": "error",
                "error_message": "wiql_query is required for query_work_items operation"
            }
        
        # Execute WIQL query
        wiql = Wiql(query=wiql_query)
        query_results = wit_client.query_by_wiql(wiql=wiql, project=project)
        
        # Extract work item IDs
        work_item_ids = []
        if query_results.work_items:
            work_item_ids = [item.id for item in query_results.work_items]
        elif query_results.work_item_relations:
            work_item_ids = [relation.target.id for relation in query_results.work_item_relations]
        
        # Fetch full work item details if IDs found
        work_items = []
        if work_item_ids:
            # Batch fetch work items (limit to 200 per batch as per API limits)
            for i in range(0, len(work_item_ids), 200):
                batch_ids = work_item_ids[i:i+200]
                batch_items = wit_client.get_work_items(ids=batch_ids)
                work_items.extend([{
                    "id": item.id,
                    "url": item.url,
                    "fields": item.fields
                } for item in batch_items])
        
        return {
            "status": "success",
            "result": {
                "count": len(work_items),
                "work_items": work_items
            }
        }
    
    except Exception as e:
        return {
            "status": "error",
            "error_message": f"Failed to query work items: {str(e)}"
        }


async def _get_board_columns(
    organization_url: str,
    project: str,
    team: Optional[str],
    board_name: Optional[str],
    pat: str
) -> Dict[str, Any]:
    """Retrieve board columns configuration using REST API."""
    try:
        if not team:
            return {
                "status": "error",
                "error_message": "team is required for get_board_columns operation"
            }
        
        if not board_name:
            return {
                "status": "error",
                "error_message": "board_name is required for get_board_columns operation"
            }
        
        # Encode PAT for Basic Authentication
        encoded_pat = base64.b64encode(f":{pat}".encode()).decode()
        headers = {
            "Authorization": f"Basic {encoded_pat}",
            "Content-Type": "application/json"
        }
        
        # Build API URL
        api_url = f"{organization_url}/{project}/{team}/_apis/work/boards/{board_name}/columns?api-version=7.1"
        
        # Make REST API call
        response = requests.get(api_url, headers=headers)
        response.raise_for_status()
        
        columns_data = response.json()
        
        return {
            "status": "success",
            "result": {
                "count": columns_data.get("count", 0),
                "columns": columns_data.get("value", [])
            }
        }
    
    except requests.exceptions.HTTPError as e:
        return {
            "status": "error",
            "error_message": f"HTTP error getting board columns: {e.response.status_code} - {e.response.text}"
        }
    except Exception as e:
        return {
            "status": "error",
            "error_message": f"Failed to get board columns: {str(e)}"
        }


async def _move_to_swimlane(
    wit_client,
    organization_url: str,
    project: str,
    team: Optional[str],
    board_name: Optional[str],
    work_item_id: Optional[int],
    swimlane_name: Optional[str],
    pat: str
) -> Dict[str, Any]:
    """Move a work item to a specific swimlane."""
    try:
        if not team:
            return {
                "status": "error",
                "error_message": "team is required for move_to_swimlane operation"
            }
        
        if not board_name:
            return {
                "status": "error",
                "error_message": "board_name is required for move_to_swimlane operation"
            }
        
        if work_item_id is None:
            return {
                "status": "error",
                "error_message": "work_item_id is required for move_to_swimlane operation"
            }
        
        if not swimlane_name:
            return {
                "status": "error",
                "error_message": "swimlane_name is required for move_to_swimlane operation"
            }
        
        # Step 1: Get board information to find the swimlane field reference name
        encoded_pat = base64.b64encode(f":{pat}".encode()).decode()
        headers = {
            "Authorization": f"Basic {encoded_pat}",
            "Content-Type": "application/json"
        }
        
        board_api_url = f"{organization_url}/{project}/{team}/_apis/work/boards/{board_name}?api-version=7.1"
        
        response = requests.get(board_api_url, headers=headers)
        response.raise_for_status()
        board_data = response.json()
        
        # Extract the rowField reference name (swimlane field with GUID)
        row_field_ref_name = None
        if 'fields' in board_data and 'rowField' in board_data['fields']:
            row_field_ref_name = board_data['fields']['rowField'].get('referenceName')
        
        if not row_field_ref_name:
            return {
                "status": "error",
                "error_message": "Could not find swimlane field (rowField) for the board. The board may not have swimlanes configured."
            }
        
        # Step 2: Update the work item with the swimlane field
        document = [
            JsonPatchOperation(
                op='add',
                path=f'/fields/{row_field_ref_name}',
                value=swimlane_name
            )
        ]
        
        work_item = wit_client.update_work_item(
            document=document,
            id=work_item_id
        )
        
        return {
            "status": "success",
            "result": {
                "id": work_item.id,
                "swimlane_field": row_field_ref_name,
                "swimlane_value": swimlane_name,
                "message": f"Work item {work_item_id} moved to swimlane '{swimlane_name}'"
            }
        }
    
    except requests.exceptions.HTTPError as e:
        return {
            "status": "error",
            "error_message": f"HTTP error moving to swimlane: {e.response.status_code} - {e.response.text}"
        }
    except Exception as e:
        return {
            "status": "error",
            "error_message": f"Failed to move work item to swimlane: {str(e)}"
        }
